  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the final booking price after applying membership discount rules.
   * Algorithm:
   * 1. If customer is null or bookingTime is null, return the original trip price.
   * 2. If customer has no membershipPackage, return the original trip price.
   * 3. Verify the membershipPackage contains the DISCOUNTS award.
   * 4. If DISCOUNTS is absent, return the original trip price.
   * 5. Check whether bookingTime is at least 24 hours before departureTime.
   * 6. If the 24-hour condition is satisfied, compute price * 0.8.
   * 7. Round the result to one decimal place.
   * 8. Otherwise return the original trip price.
   * Related Features:
   * - price
   * - departureTime
   * - calculateDiscountedPrice(customer, bookingTime)
   * - driver
   * - bookings
   * - MembershipPackage.hasAward(award)
   * Related Classes: Customer, MembershipPackage, Award
   * Input:
   * - customer: Customer; must own a membership package with DISCOUNTS to qualify.
   * - bookingTime: String; booking timestamp, must be comparable to departureTime.
   * Output:
   * - double; discounted price rounded to one decimal place, or the original trip price if ineligible.
   * Pre-condition:
   * - Trip price is defined.
   * - departureTime and bookingTime are valid comparable time values.
   * Post-condition:
   * - No persistent state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return getPrice();
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return getPrice();
    }
    if (getDepartureTime() == null)
    {
      return getPrice();
    }
    long bookingMillis;
    long departureMillis;
    try
    {
      bookingMillis = Long.parseLong(bookingTime);
      departureMillis = Long.parseLong(getDepartureTime());
    }
    catch (NumberFormatException e)
    {
      return getPrice();
    }
    long diff = departureMillis - bookingMillis;
    if (diff >= 24L * 60L * 60L * 1000L)
    {
      return Math.round(getPrice() * 0.8 * 10.0) / 10.0;
    }
    return getPrice();
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Compute points earned for this trip's bookings by a customer within a specified month.
   * Algorithm:
   * 1. If customer is null or currentMonth is null, return 0.
   * 2. If customer has no membershipPackage, return 0.
   * 3. Verify the membershipPackage contains the POINTS award.
   * 4. Iterate through this trip's bookings.
   * 5. Count only bookings belonging to the specified customer and whose bookingDate falls in currentMonth.
   * 6. Add 5 points per booked seat for each qualifying booking.
   * 7. Return the total.
   * Related Features:
   * - bookings
   * - calculateMonthlyPoints(customer, currentMonth)
   * - getBookedSeats()
   * - Booking.bookingDate
   * - Booking.numberOfSeats
   * - Booking.isInMonth(month)
   * - MembershipPackage.hasAward(award)
   * Related Classes: Customer, Booking, MembershipPackage, Award
   * Input:
   * - customer: Customer; the customer whose points are computed.
   * - currentMonth: String; requested month, system-supported month format.
   * Output:
   * - int; reward points earned for the trip in the requested month, or 0 when ineligible.
   * Pre-condition:
   * - Trip and customer objects exist.
   * - Booking dates are available for comparison.
   * - Membership package, if present, can be queried.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
    {
      return 0;
    }
    int total = 0;
    for (Booking booking : getBookings())
    {
      if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
      {
        total += booking.getNumberOfSeats() * 5;
      }
    }
    return total;
  }

